document.querySelectorAll('[data-lab="G04-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready="1";const input=root.querySelector("[data-position]"),en=root.dataset.lang==="en";function draw(){const x=Number(input.value),d=x-.1,mi=d-3*Math.round(d/3),px=60+x*260;root.querySelector("[data-point]").setAttribute("cx",px);root.querySelector("[data-label]").setAttribute("x",Math.max(62,Math.min(818,px-7)));root.querySelector("[data-direct]").setAttribute("d","M86 105 H"+px);let path;if(Math.abs(d)<=1.5){path="M86 140 H"+px;}else{path=d>0?"M86 140 H60 M840 140 H"+px:"M86 140 H840 M60 140 H"+px;}root.querySelector("[data-nearest]").setAttribute("d",path);root.querySelector("[data-readout]").textContent=en?"B = "+x.toFixed(2)+" nm; direct distance = "+Math.abs(d).toFixed(2)+" nm; nearest periodic distance = "+Math.abs(mi).toFixed(2)+" nm.":"B = "+x.toFixed(2)+" nm；直接距离 = "+Math.abs(d).toFixed(2)+" nm；最短周期距离 = "+Math.abs(mi).toFixed(2)+" nm。";}input.addEventListener("input",draw);root.querySelector("[data-reset]").addEventListener("click",()=>{input.value="2.9";draw();});draw();});